<script setup>import{inject,ref}from'vue';import api from '../../../../services/api';import AddMemberModal from '../../../../components/admin/AddMemberModal.vue';const s=inject('clinicAdmin'),open=ref(false);async function add(data){try{await s.run(async()=>{await api.post('/v1/platform/tenants/'+s.clinic.value.id+'/members',data);await s.load(s.clinic.value.id)},'Member created.');open.value=false}catch{}}async function save(member){await s.run(async()=>{await api.patch('/v1/platform/tenants/'+s.clinic.value.id+'/members/'+member.id,{role:member.role,status:member.status});await s.load(s.clinic.value.id)},'Membership saved.')}</script><template><section class="admin-card"><div class="card-heading"><div><h2>Members</h2><p class="text-sm text-slate-500">People with access to this clinic.</p></div><button class="btn" @click="open=true">+ Add Member</button></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Branch</th><th>Status</th><th>Last Activity</th><th>Actions</th></tr></thead><tbody><tr v-for="member in s.members.value" :key="member.id"><td class="font-semibold">{{member.name}}</td><td>{{member.email}}</td><td><select v-model="member.role" class="compact-select"><option>owner</option><option>admin</option><option>staff</option></select></td><td>Not assigned</td><td><select v-model="member.status" class="compact-select"><option>active</option><option>suspended</option></select></td><td>Not available</td><td><button class="btn-secondary" @click="save(member)">Save</button></td></tr></tbody></table></div><AddMemberModal :open="open" @close="open=false" @save="add"/></section></template>
